import { stressApp as app } from './swiftui-stress-cases'
export interface VisualCase { name: string; source: string; gap?: string; text?: string }
const state = '@State var shown = true; @State var flag = true; @State var text = "Taylor"; @State var choice = 0; @State var amount = 0.65; @State var count = 2; @State var date = Date(timeIntervalSince1970: 1750000000); @State var color = Color.blue'
const test = (name: string, body: string, text?: string, gap?: string, extra = ''): VisualCase => ({ name, source: app(body, state, extra), text, gap })
const picker = 'Picker("Range", selection: $choice) { Text("Day").tag(0); Text("Week").tag(1); Text("Month").tag(2) }'
export const visualCases: VisualCase[] = [
  ...['medium', 'large', 'fraction(0.3)', 'height(200)'].map(detent => test(`sheet-${detent}`, `Text("Base").sheet(isPresented: $shown) { Text("Sheet content").presentationDetents([.${detent}]) }`, 'Sheet content')),
  test('sheet-custom', 'Text("Base").sheet(isPresented: $shown) { Text("Sheet content").presentationDetents([.medium, .large]).presentationCornerRadius(28).presentationDragIndicator(.visible).presentationBackground(.yellow) }', 'Sheet content'),
  test('sheet-material', 'Text("Base").sheet(isPresented: $shown) { Text("Sheet content").presentationBackground(.thinMaterial) }', 'Sheet content'),
  test('sheet-dismiss-disabled', 'Text("Base").sheet(isPresented: $shown) { Text("Locked").interactiveDismissDisabled() }', 'Locked'),
  test('sheet-background-interaction', 'Text("Base").sheet(isPresented: $shown) { Text("Sheet").presentationBackgroundInteraction(.enabled) }', 'Sheet'),
  test('fullScreenCover', 'Text("Base").fullScreenCover(isPresented: $shown) { Text("Cover") }', 'Cover'),
  test('popover', 'Text("Base").popover(isPresented: $shown) { Text("Popover") }', 'Popover'),
  test('alert-fields', 'Text("Base").alert("Rename", isPresented: $shown) { TextField("Name", text: $text); SecureField("Password", text: $text); Button("Save") {} } message: { Text("Enter a name") }', 'Enter a name'),
  test('confirmationDialog', 'Text("Base").confirmationDialog("Action", isPresented: $shown, titleVisibility: .visible) { Button("Archive") {}; Button("Delete", role: .destructive) {}; Button("Cancel", role: .cancel) {} }', 'Archive'),
  test('inspector', 'Text("Base").inspector(isPresented: $shown) { Text("Inspector") }', 'Inspector'),
  ...['segmented', 'menu', 'wheel', 'inline', 'navigationLink', 'palette'].map(style => test(`picker-${style}`, `${picker}.pickerStyle(.${style})`, undefined, ['palette', 'navigationLink'].includes(style) ? style : undefined)),
  test('toggle-switch', 'Toggle("Notifications", isOn: $flag)', 'Notifications'),
  test('toggle-button', 'Toggle("Favorite", isOn: $flag).toggleStyle(.button)', 'Favorite'),
  test('slider', 'Slider(value: $amount, in: 0...1)'),
  test('stepper', 'Stepper("Quantity", value: $count, in: 0...10)', 'Quantity'),
  ...['compact', 'graphical', 'wheel'].map(style => test(`date-${style}`, `DatePicker("When", selection: $date).datePickerStyle(.${style})`, 'When', 'datePickerStyle')),
  test('MultiDatePicker', 'MultiDatePicker("Dates", selection: .constant([]))', undefined, 'MultiDatePicker'),
  test('ColorPicker', 'ColorPicker("Tint", selection: $color)', 'Tint'),
  test('PhotosPicker', 'PhotosPicker(selection: Binding<PhotosPickerItem?>.constant(nil), matching: .images) { Text("Photos") }', undefined, 'PhotosPicker', 'import PhotosUI'),
  ...['bordered', 'borderedProminent', 'borderless', 'plain'].map(style => test(`button-${style}`, `Button("Action") {}.buttonStyle(.${style})`, 'Action')),
  test('Menu', 'Menu("Actions") { Button("Archive") {}; Button("Delete") {} }', 'Actions'),
  test('ControlGroup', 'ControlGroup { Button("Copy") {}; Button("Paste") {} }', 'Copy'),
  test('contextMenu', 'Text("Row").contextMenu { Button("Copy") {} } preview: { Text("Preview") }', 'Row', 'contextMenu'),
  test('Link', 'Link("Website", destination: URL(string: "https://example.com")!)', 'Website', 'Link'),
  test('ShareLink', 'ShareLink("Share", item: "Sample")', 'Share', 'ShareLink'),
  ...['EditButton', 'RenameButton'].map(view => test(view, `${view}()`, undefined, view)),
  test('PasteButton', 'PasteButton(payloadType: String.self) { _ in }', undefined, 'PasteButton'),
  test('TextField', 'TextField("Name", text: $text)'),
  test('SecureField', 'SecureField("Password", text: $text)'),
  test('TextEditor', 'TextEditor(text: $text).frame(height: 120)'),
  test('searchable', 'NavigationStack { List { Text("Result") }.searchable(text: $text).navigationTitle("Search") }', 'Result'),
  test('searchScopes', 'NavigationStack { List { Text("Result") }.searchable(text: $text).searchScopes($choice) { Text("All").tag(0); Text("Saved").tag(1) } }', 'Result', 'searchScopes'),
  test('searchSuggestions', 'NavigationStack { List { Text("Result") }.searchable(text: $text).searchSuggestions { Text("Suggested") } }', 'Result', 'searchSuggestions'),
  ...['keyboard', 'bottomBar', 'principal'].map(placement => test(`toolbar-${placement}`, `NavigationStack { Text("Base").toolbar { ToolbarItem(placement: .${placement}) { Button("Extra") {} } } }`, 'Base', placement)),
  test('navigation', 'NavigationStack { NavigationLink("Details") { Text("Destination") }.navigationTitle("Library").navigationBarTitleDisplayMode(.inline).toolbar { ToolbarItem(placement: .topBarTrailing) { Button("Compose") {} } } }', 'Compose'),
  test('NavigationSplitView', 'NavigationSplitView { Text("Sidebar") } detail: { Text("Detail") }', 'Sidebar'),
  test('modern-tabs', 'TabView { Tab("Home", systemImage: "house") { Text("Home screen") }; Tab("Saved", systemImage: "star") { Text("Saved screen") } }', 'Home screen'),
  test('sidebar-tabs', 'TabView { Text("Home").tabItem { Text("Home") } }.tabViewStyle(.sidebarAdaptable)', 'Home', 'sidebarAdaptable'),
  test('page-tabs', 'TabView { Text("First"); Text("Second") }.tabViewStyle(.page)', 'First'),
  test('list', 'List { Section("Section") { Text("Row") } }', 'Row'),
  test('form', 'Form { Section("Section") { Toggle("Flag", isOn: $flag); TextField("Name", text: $text) } }', 'Flag'),
  test('swipeActions', 'List { Text("Row").swipeActions { Button("Archive") {} } }', 'Row', 'swipeActions'),
  test('onDelete', 'List { ForEach(0..<3) { Text("Row \\($0)") }.onDelete { offsets in count = offsets.count } }', 'Row 0'),
  test('onMove', 'List { ForEach(0..<3) { Text("Row \\($0)") }.onMove { _, _ in } }', 'Row 0', 'onMove'),
  test('refreshable', 'List { Text("Row") }.refreshable { count += 1 }', 'Row', 'refreshable'),
  test('DisclosureGroup', 'DisclosureGroup("More", isExpanded: $flag) { Text("Expanded") }', 'Expanded'),
  test('OutlineGroup', 'OutlineGroup([Node(id: 1)], children: \\.children) { Text("Node \\($0.id)") }', undefined, 'OutlineGroup', 'struct Node: Identifiable { let id: Int; var children: [Node]? = nil }'),
  test('GroupBox', 'GroupBox("Summary") { Text("Details") }', 'Details'),
  test('LabeledContent', 'LabeledContent("Version", value: "1.0")', '1.0'),
  test('LazyVGrid', 'LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())]) { ForEach(0..<8) { Text("Cell \\($0)") } }', 'Cell 7'),
  test('LazyHGrid', 'LazyHGrid(rows: [GridItem(.fixed(40)), GridItem(.fixed(40))]) { ForEach(0..<8) { Text("Cell \\($0)") } }', 'Cell 7'),
  test('Grid', 'Grid { GridRow { Text("A"); Text("Longer B") }; GridRow { Text("C"); Text("D") } }', 'D'),
  test('Table', 'Table([Row(id: 1)]) { TableColumn("Value") { row in Text("Value \\(row.id)") } }', undefined, 'Table', 'struct Row: Identifiable { let id: Int }'),
  test('ContentUnavailableView', 'ContentUnavailableView("No results", systemImage: "magnifyingglass", description: Text("Try another search"))', 'Try another search'),
  test('progress-spinner', 'ProgressView()'),
  test('progress-linear', 'ProgressView("Download", value: amount)', 'Download'),
  ...['linearCapacity', 'accessoryLinear', 'accessoryLinearCapacity', 'accessoryCircular', 'accessoryCircularCapacity'].map(style => test(`gauge-${style}`, `Gauge(value: amount) { Text("Used") } currentValueLabel: { Text("65%") }.gaugeStyle(.${style})`, '65%')),
  test('badge', 'TabView { Text("Home").tabItem { Text("Home") }.badge(3) }', 'Home'),
  test('popoverTip', 'Text("Help").popoverTip(HelpTip())', 'Help', 'popoverTip', 'import TipKit; struct HelpTip: Tip { var title: Text { Text("A useful tip") } }'),
  test('fileImporter', 'Text("Files").fileImporter(isPresented: $shown, allowedContentTypes: [.plainText]) { _ in }', 'Files', 'fileImporter', 'import UniformTypeIdentifiers'),
  test('fileExporter', 'Text("Files").fileExporter(isPresented: $shown, document: Optional<TextFile>.none, contentType: .plainText) { _ in }', undefined, 'fileExporter', 'import UniformTypeIdentifiers; struct TextFile: FileDocument { static var readableContentTypes: [UTType] { [.plainText] }; init(configuration: ReadConfiguration) throws {}; func fileWrapper(configuration: WriteConfiguration) throws -> FileWrapper { FileWrapper(regularFileWithContents: Data()) } }'),
]
